        needs_help: list = [];

    can analyze with Student entry {
        # Find enrollment information
        enrollments = [->:EnrolledIn:->];

        for enrollment_edge in [->:EnrolledIn:->] {
            grade = enrollment_edge.grade;
            attendance = enrollment_edge.attendance_rate;

