            emotional_state=emotional_state,
            intent=intent_analysis,
            extracted=extracted_tasks,
            attachment=attachment_analysis,
            convergence=convergence_intent
        );

        task_names = [];
        for rel in relationships {
            if rel.to_task not in task_names {
                task_names.append(rel.to_task);
            }
        }

        response = generate_friendly_response(
            user_message=self.context_from_user,
            emotional_state=emotional_state,
            action_taken="task_added"
                if intent_analysis.should_create_tasks
                else "none",
            task_names=task_names
        );

        suggestions = [];
        try {
            recent_tasks = [];
            task_count = 0;
            for i in range(len(current_nodes) - 1, -1, -1) {
                if current_nodes[i] != "Start" and task_count < 3 {
                    recent_tasks.insert(0, current_nodes[i]);
                    task_count = task_count + 1;
                }
            }

            suggestions = generate_next_suggestions(
                last_task=last_task,
                recent_tasks=recent_tasks,
                context=intent_analysis.context,
                emotional_state=emotional_state
            );
        } except Exception as e {
            suggestions = [];
        }

        thinking = {
            "emotional": thinking_summary.emotional_insight
                if thinking_summary.emotional_insight
                else "",
            "intent": thinking_summary.intent_insight
                if thinking_summary.intent_insight
                else "",
            "tasks": thinking_summary.task_insight
                if thinking_summary.task_insight
                else "",
            "pattern": thinking_summary.pattern_insight
                if thinking_summary.pattern_insight
                else ""
        };

        user_graph_after = find_user_graph(here, self.username);
        after_nodes = [];
        after_edges = [];
        if user_graph_after {
            graph_data = get_user_graph_structure(user_graph_after);
            after_nodes = graph_data[0];
            after_edges = graph_data[1];
        }

        manager_data = find_manager_comm_data(here, self.username);
        if not manager_data {
            manager_data = manager_comm_data(username=self.username);
            here ++> manager_data;
        }
        manager_data.last_response = response;
        manager_data.last_suggestions = suggestions;
        manager_data.last_thinking = thinking;
        manager_data.last_task_names = task_names;
        manager_data.last_emotional_state = str(emotional_state.emotion);

        intent_dict = {
            "conversation_context": {
                "intent": str(intent_analysis.context.intent),
                "referring_to_task": intent_analysis.context.referring_to_task,
                "correction_type": str(intent_analysis.context.correction_type),
                "tasks_to_move": intent_analysis.context.tasks_to_move
            },
            "should_create_tasks": intent_analysis.should_create_tasks,
            "confidence": intent_analysis.confidence
        };

        root spawn validate_graph_output(
            context_from_user=self.context_from_user,
            username=self.username,
            intent_analysis=intent_dict,
