"""Generic code block component with copy functionality (for non-Jac languages)."""
def:pub CodeBlock(language: str, code: str, children: any = null) -> JsxElement {
    has copied: bool = false;

    def handleCopy() -> None {
        navigator.clipboard.writeText(code);
        copied = true;
        setTimeout(lambda { copied = false; }, 2000);
    }

    copyLabel = "Copy code";
    copyColor = "gray";
    copyIcon = <IconCopy size={14} />;
    if copied {
        copyLabel = "Copied!";
        copyColor = "green";
        copyIcon = <IconCheck size={14} />;
    }

    displayLang = language;
    if not displayLang {
        displayLang = "code";
    }

    return <Box my="sm">
        <Paper
            radius="md"
            style={{
                "background": "rgba(0,0,0,0.42)",
                "border": "1px solid rgba(255,255,255,0.10)",
                "overflow": "hidden"
            }}
        >
            <Group
                justify="space-between"
                px="md"
                py="xs"
                style={{
                    "borderBottom": "1px solid rgba(255,255,255,0.06)",
                    "background": "rgba(0,0,0,0.25)"
                }}
            >
                <Text size="xs" c="dimmed" ff="monospace">
                    {displayLang}
                </Text>
                <Tooltip label={copyLabel} position="left">
                    <ActionIcon
                        onClick={handleCopy}
                        variant="subtle"
                        color={copyColor}
                        size="sm"
                    >
                        {copyIcon}
                    </ActionIcon>
                </Tooltip>
            </Group>
            <Box px="md" py="sm" style={{"overflowX": "auto"}}>
                <pre
                    style={{
                        "margin": "0",
                        "padding": "0",
                        "fontSize": "13px",
                        "lineHeight": "1.6",
                        "fontFamily": "JetBrains Mono, Consolas, Monaco, monospace",
                        "whiteSpace": "pre-wrap",
                        "wordBreak": "break-word",
                        "color": "#e4e4e7"
                    }}
                    onCut={lambda e: any -> None { e.preventDefault(); }}
                    onPaste={lambda e: any -> None { e.preventDefault(); }}
                    onKeyDown={lambda e: any -> None {
                        isCopy = (e.ctrlKey or e.metaKey) and (e.key == "c" or e.key == "C");
                        isSelectAll = (e.ctrlKey or e.metaKey) and (e.key == "a" or e.key == "A");
                        if (e.ctrlKey or e.metaKey) and not isCopy and not isSelectAll {
                            e.preventDefault();
                        }
                    }}
                >
                    <code>{code}</code>
                </pre>
            </Box>
        </Paper>
    </Box>;
}


"""Read-only Jac code block using CodeMirror 6."""
def:pub JacCodeBlock(code: str) -> JsxElement {
    has copied: bool = false;
    editorRef = useRef(None);
    viewRef = useRef(None);

    def handleCopy() -> None {
        navigator.clipboard.writeText(code);
        copied = true;
        setTimeout(lambda { copied = false; }, 2000);
    }

    # Create / destroy the CodeMirror EditorView when code changes
    useEffect(lambda {
        if viewRef.current {
            viewRef.current.destroy();
            viewRef.current = None;
        }
        if editorRef.current {
            state = EditorState.create({
                "doc": code,
                "extensions": [
                    getJacExtensions(),
                    EditorState.readOnly.of(True),
                    EditorView.editable.of(False)
                ]
