    visGraph = useMemo(lambda -> any {
        if not hasGraphData {
            return None;
        }

        nodes = graphData.nodes.map(lambda n: any -> dict {
            isRoot = n.label == "root";
            colors = getNodeColors(n.label, isRoot);

            return {
