"""Integration tests for output/reporter.jac — JSON schema, HTML structure, stdout/file routing."""

import json;
import tempfile;
import os;
import from jac_loadtest_cli.config { LoadTestConfig }
import from jac_loadtest_cli.core.metrics { EndpointStats, StatsSnapshot }
import from jac_loadtest_cli.output.reporter { render_console, render_json, render_html }


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _make_config(
    har_file: str = "test.har",
    url: str = "http://localhost:8000",
    mode: str = "monolith",
    vus: int = 10,
    workers: int = 1,
    ramp_up: str = "0s",
    timeout: str = "30s",
    report_format: str = "console",
    report_out: str | None = None,
    max_samples: int = 1_000_000,
) -> LoadTestConfig {
    return LoadTestConfig(
        har_file=har_file,
        url=url,
        mode=mode,
        vus=vus,
        workers=workers,
        ramp_up=ramp_up,
        timeout=timeout,
        report_format=report_format,
        report_out=report_out,
        max_samples=max_samples,
    );
}

def _make_stats(
    endpoint: str = "POST /walker/search",
    service: str = "monolith",
    total: int = 100,
    success: int = 98,
    p50: float = 45.0,
    p95: float = 120.0,
    p99: float = 250.0,
    ttfb_ms: float = 30.0,
) -> EndpointStats {
    return EndpointStats(
        endpoint=endpoint,
        service=service,
        total_requests=total,
        success_count=success,
        error_count=total - success,
        success_rate_pct=round(success / total * 100, 1),
        min_ms=10.0,
        max_ms=500.0,
        mean_ms=p50,
        p50_ms=p50,
        p95_ms=p95,
        p99_ms=p99,
        latencies=[],
        error_breakdown={"500": total - success} if total > success else {},
        ttfb_ms=ttfb_ms,
    );
}

def _make_snapshot(t: float = 5.0) -> StatsSnapshot {
    return StatsSnapshot(
        timestamp=t,
        p50_ms=40.0,
        p95_ms=110.0,
        p99_ms=220.0,
        rps=5.5,
        error_rate_pct=1.0,
    );
}


