                                <Icon size={16} />
                            </button>
                        );
                    })}
                </div>
            </div>
        );
    }

    return (
        <div className="h-full w-64 bg-surface border-l border-border flex flex-col">
            <div className="flex items-center justify-between px-3 h-10 border-b border-border">
                <div className="flex items-center gap-1">
