                    <Text size="xl" fw={700} c={TEXT}>Access Denied</Text>
                    <Text c={MUTED} size="sm">Admin privileges required to access this page.</Text>
                    <Button
                        onClick={lambda -> None { navigate("/"); }}
                        leftSection={<IconArrowLeft size={16} />}
                        styles={{
                            "root": {
