                </Stack>
            </Paper>
        </Box>;
    }

    # Filter out empty sessions (created on page load but never used)
    activeSessions_list = sessions.filter(lambda s: any -> any {
        return (s.message_count or 0) > 0;
    });

    # --- Compute stats ---
    totalMessages = 0;
    activeSessions = 0;
    adminCount = 0;
    userCount = 0;

    for s in activeSessions_list {
