from tkinter import *


def get_room(i2d, dbname):
    ret = None

    con = sqlite3.connect(dbname)

    for row in con.execute("select description from rooms where id=?", (i2d,)):

        jsontext = row[0]
        d = json.loads(jsontext)
        d['id'] = i2d
        ret = Room(**d)
        break

    con.close()
    return ret


