BOOLEAN = 'boolean'
COMPARATIVE = 'comparative'


class BoolFilterSpec():
    """Boolean filter specification"""

    type = BOOLEAN

    def __init__(self, func, *, needed_keys=(), aliases=(), description='No description'):
        if not func:
            self.filter_function = None
