    has id: str,
        content: str,
        author_username: str,
        created_at: str,
        likes: list[str],
        comments: list[dict[str, str]],
        is_mine: bool = False;
}

obj ProfileView {
    has id: str,
        username: str,
        bio: str,
        followers: list[UserView],
        following: list[UserView],
        tweets: list[TweetView];
}

obj ChannelView {
    has id: str,
        name: str,
        description: str,
        creator_username: str,
        created_at: str,
        member_count: int,
        is_member: bool,
        posts: list[TweetView] = [];
}

obj TrendingTag {
    has tag: str,
        count: int;
}

# --- Edges: the relationships in the social graph ---
